 "content": "from collections import deque, Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    rects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            area = (r1-r0+1) * (c1-c0+1)
            # Large, nearly solid components are the rectangular objects; isolated
            # differently-colored pixels are noise to be erased.
            if area >= 4 and len(cells) / area >= 0.75:
                rects.append((r0, r1, c0, c1, color))
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r0, r1, c0, c1, color in rects:
        for y in range(r0, r1 + 1):
            for x in range(c0, c1 + 1):
                out[y][x] = color
    return out
